void set_error_routine(void (*routine)(const char *err, va_list params)) /* <=== set_error_routine */ 
{
	error_routine = routine;
}

void child_process_clear(struct child_process *child) /* <=== child_process_clear */ 
{
	argv_array_clear(&child->args);
	argv_array_clear(&child->env_array);
}

static void mark_child_for_cleanup(pid_t pid, struct child_process *process) /* <=== mark_child_for_cleanup */ 
{
	struct child_to_clean *p = xmalloc(sizeof(*p));
	p->pid = pid;
	p->process = process;
	p->next = children_to_clean;
	children_to_clean = p;

	if (!installed_child_cleanup_handler) {
		atexit(cleanup_children_on_exit);
		sigchain_push_common(cleanup_children_on_signal);
		installed_child_cleanup_handler = 1;
	}
}

void NORETURN die(const char *err, ...) /* <=== die */ 
{
	va_list params;

	if (die_is_recursing()) {
		fputs("fatal: recursion detected in die handler\n", stderr);
		exit(128);
	}

	va_start(params, err);
	die_routine(err, params);
	va_end(params);
}

static void *xstrdup(const char *s1) /* <=== xstrdup */ 
{
	void *ret = strdup(s1);
	if (!ret)
		die("Out of memory");
	return ret;
}

static void atfork_prepare(struct atfork_state *as) /* <=== atfork_prepare */ 
{
	sigset_t all;

	if (sigfillset(&all))
		die_errno("sigfillset");
#ifdef NO_PTHREADS
	if (sigprocmask(SIG_SETMASK, &all, &as->old))
		die_errno("sigprocmask");
#else
	bug_die(pthread_sigmask(SIG_SETMASK, &all, &as->old),
		"blocking all signals");
	bug_die(pthread_setcancelstate(PTHREAD_CANCEL_DISABLE, &as->cs),
		"disabling cancellation");
#endif
}

static inline FORMAT_PRESERVING(1) const char *_(const char *msgid) /* <=== _ */ 
{
	if (!*msgid)
		return "";
	return use_gettext_poison() ? "# GETTEXT POISON #" : gettext(msgid);
}

static inline void set_cloexec(int fd) /* <=== set_cloexec */ 
{
	int flags = fcntl(fd, F_GETFD);
	if (flags >= 0)
		fcntl(fd, F_SETFD, flags | FD_CLOEXEC);
}

static void argv_array_push_nodup(struct argv_array *array, const char *value) /* <=== argv_array_push_nodup */ 
{
	if (array->argv == empty_argv)
		array->argv = NULL;

	ALLOC_GROW(array->argv, array->argc + 2, array->alloc);
	array->argv[array->argc++] = value;
	array->argv[array->argc] = NULL;
}

static inline void close_pair(int fd[2]) /* <=== close_pair */ 
{
	close(fd[0]);
	close(fd[1]);
}

static void die(const char *err, ...) /* <=== die */ 
{
	char msg[4096];
	va_list params;
	va_start(params, err);
	vsnprintf(msg, sizeof(msg), err, params);
	fprintf(stderr, "%s\n", msg);
	va_end(params);
	exit(1);
}

